const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {start}=require('./helpers/audit-harness.cjs');
const tests=[],results=[];const test=(id,area,name,run,options={})=>tests.push({id,area,name,run,options});
const tick=p=>p.waitForTimeout(100);
async function advanced(s){await s.page.locator('#systemOpen412').click();await s.page.locator('#systemAdvanced412').evaluate(e=>e.closest('details').open=true)}
async function supplier(s,name){await advanced(s);await s.page.locator('#newSupplierName').fill(name);await s.page.locator('#btnAddSupplier').click();await tick(s.page)}
async function mapping(s,primary='4901071404000',alias='4909999999999'){await advanced(s);await s.page.locator('#mapPrimaryBarcode').evaluate(e=>e.closest('details').open=true);await s.page.locator('#mapPrimaryBarcode').fill(primary);await s.page.locator('#mapAliasBarcode').fill(alias);await s.page.locator('#btnAddMapping').click();await tick(s.page)}
async function quote(s,price='100'){await s.imports('quotes');await s.page.locator('#inputBarcode').fill('4901071404000');await s.page.locator('#inputBarcode').blur();await s.page.locator('#inputSupplier').selectOption('SilkRoad');await s.page.locator('#inputContainer').fill('AUDIT-Q001');await s.page.locator('#inputPrice').fill(price)}
async function submitQuote(s){await s.page.locator('#priceForm button[type="submit"]').click();await tick(s.page)}
async function inventory(s,text){await s.imports('planner');const {frame}=await s.planner();await s.imports('planner');await frame.locator('#importMYOB').click();await frame.locator('#inventoryPaste').fill(text);await frame.locator('#previewInventoryPaste').click();return frame}
test('AUTH-01','登入與角色','未登入不顯示主頁',async s=>{assert(await s.page.locator('#authGate').isVisible());assert(!await s.page.locator('#protectedApp').isVisible())},{signedIn:false});
test('AUTH-02','登入與角色','錯誤密碼顯示錯誤並可重試',async s=>{await s.page.locator('#loginEmail').fill('audit@example.com');await s.page.locator('#loginPassword').fill('wrong');await s.page.locator('#btnLogin').click();await s.page.locator('#loginError:not(.d-none)').waitFor();assert(!await s.page.locator('#btnLogin').isDisabled());assert(!await s.page.locator('#protectedApp').isVisible())},{signedIn:false});
test('AUTH-03','登入與角色','正確登入並清空密碼',async s=>{await s.page.locator('#loginEmail').fill('audit@example.com');await s.page.locator('#loginPassword').fill('test-password');await s.page.locator('#btnLogin').click();await s.page.locator('#protectedApp:not(.d-none)').waitFor();assert.equal(await s.page.locator('#loginPassword').inputValue(),'')},{signedIn:false});
test('AUTH-04','登入與角色','未核准帳號被阻擋',async s=>{await s.page.locator('#loginError:not(.d-none)').waitFor();assert(!await s.page.locator('#protectedApp').isVisible())},{role:'disabled'});
test('AUTH-05','登入與角色','Viewer 隱藏匯入與管理功能',async s=>{assert(!await s.page.locator('#add-tab').isVisible());assert(!await s.page.locator('#settings-tab').isVisible());assert(!await s.page.locator('#btnUsers').isVisible())},{role:'viewer'});
test('AUTH-06','登入與角色','Editor 可開訂貨、不能管理商品主檔',async s=>{assert(await s.page.locator('#add-tab').isVisible());assert(!await s.page.locator('#settings-tab').isVisible());await s.planner()},{role:'editor'});
test('AUTH-07','登入與角色','登出後主頁及兩個子頁面鎖定',async s=>{const p=await s.planner();await s.container();await s.page.locator('#btnLogout').click();await s.page.locator('#authGate:not(.d-none)').waitFor();assert(!await s.page.locator('#protectedApp').isVisible());assert.equal(await s.page.locator('#plannerFrame').getAttribute('src'),null,'登出後不應保留前一使用者的訂貨子頁面')});
test('AUTH-08','登入與角色','Viewer 切換 Admin 後恢復 PI 匯入',async s=>{await s.page.evaluate(()=>window.__setRole('admin'));await s.imports('pi');assert(!await s.page.locator('#btnImportFinalPi').isDisabled(),'Admin 的 PI 匯入按鈕不應沿用 Viewer 的 disabled 狀態')},{role:'viewer'});
