test('UX-02','已填寫篩選','顯示有箱數或備註的商品，返回全部不丟資料',async s=>{const {frame}=await s.planner();await frame.locator('#container').fill('AUDIT-REVIEW');await frame.locator('input[data-item-note="TEST002"]').fill('僅提醒');await frame.locator('#reviewWritten').click();assert.equal(await frame.locator('#productRows input[data-qty]').count(),1);assert(await frame.locator('input[data-item-note="TEST002"]').isVisible());assert.equal(await frame.locator('#reviewWritten').getAttribute('aria-pressed'),'true');await frame.locator('#reviewWritten').click();assert.equal(await frame.locator('#productRows input[data-qty]').count(),2);assert.equal(await frame.locator('input[data-item-note="TEST002"]').inputValue(),'僅提醒')});
test('UX-03','填寫順序','採用、手動與箭頭調整均保持商品原位及捲動',async s=>{const {frame,handle}=await s.planner();await frame.locator('#container').fill('AUDIT-STABLE');await frame.locator('#search').click();await handle.evaluate(()=>{const original=calc;calc=i=>({...original(i),suggest:7});renderPlan()});const before=await frame.locator('#productRows input[data-qty]').evaluateAll(es=>es.map(e=>e.dataset.qty));const row=await handle.locator('input[data-qty="TEST002"]').elementHandle();await frame.locator('[data-use="TEST002"]').scrollIntoViewIfNeeded();const y=await s.page.evaluate(()=>scrollY);await frame.locator('[data-use="TEST002"]').click();assert.deepEqual(await frame.locator('#productRows input[data-qty]').evaluateAll(es=>es.map(e=>e.dataset.qty)),before);assert(await row.evaluate(e=>e.isConnected));assert.equal(await frame.locator('input[data-qty="TEST002"]').inputValue(),'7');assert(Math.abs(await s.page.evaluate(()=>scrollY)-y)<5);await frame.locator('input[data-qty="TEST002"]').fill('9');await frame.locator('input[data-qty="TEST002"]').press('ArrowUp');await frame.locator('#search').click();assert.deepEqual(await frame.locator('#productRows input[data-qty]').evaluateAll(es=>es.map(e=>e.dataset.qty)),before);assert.equal(await frame.locator('input[data-qty="TEST002"]').inputValue(),'10')});
test('UX-04','貨櫃摘要與分區','摘要顯示階段到港與待辦，分區可展開並保留輸入',async s=>{const {frame}=await s.container();await frame.locator('button[onclick="newC()"]').click();await frame.locator('#f_code').fill('AUDIT-SUMMARY');await frame.locator('#f_status').selectOption('Shipping');await frame.locator('#f_portDate').fill('2026-12-20');assert((await frame.locator('#containerSummary').innerText()).includes('2026-12-20'));assert((await s.page.locator('#containerDetailBar').innerText()).includes('SHIPPING'));assert.equal(await frame.locator('details[data-section="Payment"]').getAttribute('open'),null);await frame.locator('details[data-section="Payment"] > summary').click();await frame.locator('#f_deposit').check();await frame.locator('details[data-section="Payment"] > summary').click();await frame.locator('details[data-section="Payment"] > summary').click();assert(await frame.locator('#f_deposit').isChecked());await s.page.screenshot({path:path.join(path.dirname(reportFile),'Next-UI-container.png')})});
test('UX-05','儲存回饋','貨櫃失敗保留表單和資料、重試成功且留在原頁',async s=>{const {frame}=await s.container();await frame.locator('button[onclick="newC()"]').click();await frame.locator('#f_code').fill('AUDIT-RETRY-CONTAINER');await frame.locator('#f_notes').fill('保留這個輸入');await s.page.evaluate(()=>window.__failWrites=true);await s.page.locator('#containerDetailBar [data-detail-action="save"]').click();await frame.locator('#containerSaveFeedback.bad').waitFor();assert(await frame.locator('#modal.show').isVisible());assert.equal(await frame.locator('#f_notes').inputValue(),'保留這個輸入');assert.equal(await s.page.evaluate(()=>window.__store['app_data/container_tracker_v1']),undefined);await s.page.evaluate(()=>window.__failWrites=false);await s.page.locator('#containerDetailBar [data-detail-action="save"]').click();await frame.locator('#containerSaveFeedback.ok').waitFor();assert(await frame.locator('#modal.show').isVisible());assert.equal(await s.page.evaluate(()=>window.__store['app_data/container_tracker_v1'].containers.length),1);await s.page.locator('#containerDetailBar [data-detail-action="back"]').click();await frame.locator('#app').waitFor({state:'visible'})});
test('UX-06','固定操作列','捲到底部仍可見外層返回與儲存操作',async s=>{const {frame}=await s.container();await frame.locator('button[onclick="newC()"]').click();await frame.locator('#f_code').fill('AUDIT-PINNED');await frame.locator('#f_status').selectOption('Shipping');await frame.locator('details[data-section="Checklist"] > summary').click();await s.page.evaluate(()=>scrollTo(0,document.body.scrollHeight));const box=await s.page.locator('#containerDetailBar').boundingBox();assert(box.y>=0&&box.y<100);assert(await s.page.locator('#containerDetailBar [data-detail-action="back"]').isVisible())});


test('UX-07','重新提交備註','清除提醒後更新會移除舊備註、保留安排設定與留言',async s=>{const {frame}=await s.planner();await frame.locator('#container').fill('AUDIT-CLEAR-NOTE');await frame.locator('#savePreset').click();await s.page.waitForFunction(()=>!!window.__store['app_data/order_planner_v1']?.drafts?.['AUDIT-CLEAR-NOTE']?.preparedAt);await frame.locator('input[data-item-note="ACE005"]').fill('舊提醒');await frame.locator('#savePlan').click();await s.page.waitForFunction(()=>window.__store['app_data/order_planner_v1'].drafts['AUDIT-CLEAR-NOTE'].itemNotes?.ACE005==='舊提醒');await frame.locator('#noteSection > summary').click();await frame.locator('#noteText').fill('保留工作單留言');await frame.locator('#sendNote').click();await s.page.waitForFunction(()=>window.__store['app_data/order_planner_v1'].drafts['AUDIT-CLEAR-NOTE'].notes?.length===1);await frame.locator('input[data-item-note="ACE005"]').fill('');await frame.locator('#savePlan').click();await s.page.waitForFunction(()=>!window.__store['app_data/order_planner_v1'].drafts['AUDIT-CLEAR-NOTE'].itemNotes?.ACE005);assert(await s.page.evaluate(()=>!!window.__store['app_data/order_planner_v1'].drafts['AUDIT-CLEAR-NOTE'].preparedAt));assert.equal(await s.page.evaluate(()=>window.__store['app_data/order_planner_v1'].drafts['AUDIT-CLEAR-NOTE'].notes[0].text),'保留工作單留言')});


async function preparedStock(s){const {frame,handle}=await s.planner();await frame.locator('#container').fill('OCT21');await frame.locator('#search').click();await handle.evaluate(()=>{const i=state.items.find(i=>i.code==='ACE005');i.stock=100;i.monthly=5;state.inventory.ACE005={stock:100,custom:'12Unit/CTN'};state.overrides.ACE005={monthly:5,maxStock:240};customerSourceReady=true;incoming=()=>({sum:10,rows:[]});orderNeed=()=>({total:0,count:0,unknown:false});renderPlan()});return {frame,handle}}
test('OCT-01','四個月銷量','只顯示四個月份，位於在途後方且可收合',async s=>{const {frame,handle}=await s.planner();await frame.locator('#salesShowMonths').check();assert.equal(await frame.locator('th.sales-month').count(),4);const cols=await frame.locator('#plan thead tr').evaluate(e=>[...e.children].map(c=>c.dataset.column||'sales'));assert.equal(cols.indexOf('shelf'),cols.indexOf('pi')+1);assert.equal(cols.findIndex(x=>x.startsWith('sales-')),cols.indexOf('shelf')+1);assert.equal(cols.filter(x=>x.startsWith('sales-')).length,4);assert(await frame.locator('td.sales-month').first().isVisible());assert.notEqual(await frame.locator('td.sales-month').first().evaluate(e=>getComputedStyle(e).backgroundColor),'rgba(0, 0, 0, 0)');await frame.locator('#salesShowMonths').uncheck();assert(!await frame.locator('td.sales-month').first().isVisible())});
test('OCT-02','單位與上限','MYOB 原始採購單位、預計銷售單位與超標提醒',async s=>{const {frame}=await preparedStock(s);assert.equal(await frame.locator('.purchase-unit').first().innerText(),'12Unit/CTN');await frame.locator('input[data-qty="ACE005"]').fill('5');assert((await frame.locator('[data-projected="ACE005"]').innerText()).includes('280'));assert((await frame.locator('[data-projected="ACE005"]').innerText()).includes('超過上限 40'));await s.page.screenshot({path:path.join(path.dirname(reportFile),'Oct21-planning.png')})});
test('OCT-03','缺資料','缺少採購單位時不使用手動倍率、不猜數字',async s=>{const {frame,handle}=await preparedStock(s);await handle.evaluate(()=>{state.inventory.ACE005.custom='';state.overrides.ACE005.factor=12;renderPlan()});assert((await frame.locator('[data-projected="ACE005"]').innerText()).includes('資料不足，無法計算'));assert.equal(await handle.evaluate(()=>factor(state.items.find(i=>i.code==='ACE005'))),null)});
test('OCT-04','人工超標','人工超標提醒後仍可確認提交',async s=>{const {frame}=await preparedStock(s);await frame.locator('input[data-qty="ACE005"]').fill('5');await frame.locator('#savePlan').click();await s.page.waitForFunction(()=>window.__store['app_data/order_planner_v1']?.drafts?.OCT21?.rows?.ACE005===5);assert(s.dialogs.some(x=>x.includes('多出 40')))});
test('OCT-05','保存期限','已有值鎖定，但匯入能覆蓋既有值',async s=>{const {frame,handle}=await s.planner();await handle.evaluate(()=>{state.overrides.ACE005={shelfLifeMonths:12};renderPlan()});assert(await frame.locator('[data-shelf="ACE005"]').isDisabled());await s.imports('planner');await frame.locator('#openUnifiedImport').click();await frame.locator('#unifiedPaste').fill('Item Code\tShelf Life (Months)\nACE005\t18');await frame.locator('#unifiedPreviewPaste').click();await frame.locator('#unifiedApply').click();await s.page.waitForFunction(()=>window.__store['app_data/order_catalog_v1']?.overrides?.ACE005?.shelfLifeMonths===18);await s.page.locator('#planner-tab').click();await handle.waitForFunction(()=>shelfLife(state.items.find(i=>i.code==='ACE005'))===18);assert.equal(await frame.locator('[data-shelf="ACE005"]').inputValue(),'18');assert(await frame.locator('[data-shelf="ACE005"]').isDisabled())});
test('OCT-06','Inactive 通知','停用成功後 Admin 有未讀通知，已讀會儲存',async s=>{const {frame}=await s.planner();await frame.locator('[data-inactive="ACE005"]').click();await s.page.waitForFunction(()=>Object.keys(window.__store['app_data/order_catalog_v1']?.items?.ACE005?.inactiveNotices||{}).length===1);await s.page.locator('#inactiveNoticeButton').click();assert.equal(await s.page.locator('#inactiveNoticeRows .unread').count(),1);assert((await s.page.locator('#inactiveNoticeRows').innerText()).includes('ACE005'));await s.page.locator('[data-read-notice]').click();await s.page.waitForFunction(()=>Object.keys(window.__store['app_data/order_planner_v1']?.noticeReads?.['audit-user-000001']||{}).length===1);await s.page.locator('#inactiveNoticeRows .unread').waitFor({state:'detached'})});
