test('OCT-08','顯示名字與留言','Admin 改自己名字，舊留言同步改名且不能收合',async s=>{const {frame}=await s.planner();await frame.locator('#container').fill('OCT-NAME');await frame.locator('input[data-qty="ACE005"]').fill('1');await frame.locator('#savePlan').click();await s.page.waitForFunction(()=>!!window.__store['app_data/order_planner_v1']?.drafts?.['OCT-NAME']);await frame.locator('#noteSection > summary').click();await frame.locator('#noteText').fill('保留舊留言');await frame.locator('#sendNote').click();await frame.locator('#notesList .note-entry').waitFor();assert(await frame.locator('#noteSection').evaluate(e=>e.open));await frame.locator('#noteSection > summary').click();assert(await frame.locator('#noteSection').evaluate(e=>e.open));await s.page.locator('#systemOpen412').click();await s.page.locator('#btnUsers').click();await s.page.locator('#refreshUsers').click();await s.page.locator('[data-profile-uid="audit-user-000001"]').fill('Sabrina');await s.page.locator('[data-save-profile="audit-user-000001"]').click();await frame.locator('#notesList').getByText(/Sabrina/).waitFor();assert((await frame.locator('#notesList').innerText()).includes('保留舊留言'))});
