test('OCT-10','PI 模糊查詢','同貨櫃每筆結果顯示品號與名稱',async s=>{await s.page.evaluate(()=>{appData.products['4900000000003']={itemCode:'KR402',name:'Kirin 紅茶'};appData.itemToBarcode.KR402='4900000000003';appData.finalPiContainers={SEARCH:{container:'SEARCH',supplier:'Tencho',rows:[{itemCode:'ACE005',barcode:'4901071404000',qty:3,unitPrice:100},{itemCode:'KR402',barcode:'4900000000003',qty:5,unitPrice:110}]}}});await s.page.locator('#container-tab').click();await s.page.locator('[data-container-view-button="pi"]').click();await s.page.locator('#finalPiSearch').fill('KR40');assert((await s.page.locator('#finalPiSearchResults').innerText()).includes('KR402'));assert((await s.page.locator('#finalPiSearchResults').innerText()).includes('Kirin 紅茶'));assert.equal(await s.page.locator('.pi-search-table tbody tr').count(),1);await s.page.screenshot({path:path.join(path.dirname(reportFile),'Oct21-pi-search.png')})});

test('OCT-11','六個月平均','四欄只影響顯示，月銷仍含前兩個月',async s=>{const {frame,handle}=await preparedStock(s);await handle.evaluate(()=>{state.overrides.ACE005.monthly=null;state.salesV1={};salesLoading=false;salesError='';salesSummary={months:['2026-04','2026-05','2026-06','2026-07','2026-08','2026-09'],coverage:[true,true,true,true,true,true],complete:true,end:'2026-09',rows:{ACE005:{net:[12,24,36,48,60,72],gross:[12,24,36,48,60,72],raw:42,count:6}}};renderPlan()});assert.equal(await handle.evaluate(()=>monthlyInfo(state.items.find(i=>i.code==='ACE005')).value),3.5);await frame.locator('#salesShowMonths').check();assert.deepEqual(await frame.locator('#productRows tr').first().locator('td.sales-month').allTextContents(),['3','4','5','6']);await s.page.setViewportSize({width:1720,height:1100});const right=await frame.locator('#plan table.product-table').evaluate(e=>e.getBoundingClientRect().right);assert(Number.isFinite(right),'expanded table should remain measurable');await s.page.screenshot({path:path.join(path.dirname(reportFile),'Oct21-four-months.png')})});
test('MYOB-01','共享快照','空白共享快照清除內附舊值；後續更新同步庫存與單位',async s=>{const {frame,handle}=await s.planner();await handle.evaluate(()=>{state.inventory.ACE005={stock:999,custom:'12Unit/CTN'};rebuildCatalog();renderAll()});await s.page.evaluate(()=>document.querySelector('#plannerFrame').contentWindow.postMessage({type:'KAISI_INVENTORY_SNAPSHOT',mode:'live',data:{}},'*'));await frame.locator('#productRows tr').first().locator('td').nth(1).getByText('未取得',{exact:true}).waitFor();assert.equal(await handle.evaluate(()=>factor(state.items.find(i=>i.code==='ACE005'))),null);await s.page.evaluate(()=>document.querySelector('#plannerFrame').contentWindow.postMessage({type:'KAISI_INVENTORY_SNAPSHOT',mode:'live',data:{rows:{ACE005:{stock:123,custom:'12Unit/CTN'}},label:'MYOB regression',updatedAt:'2026-10-21T00:00:00Z'}},'*'));await frame.locator('#productRows tr').first().locator('td').nth(1).getByText('123',{exact:true}).waitFor();assert.equal(await frame.locator('.purchase-unit').first().innerText(),'12Unit/CTN');await s.imports('planner');assert((await frame.locator('#inventorySnapshotStatus').innerText()).includes('MYOB regression'));});
test('MYOB-02','換行與重設','Windows 貼上可直接套用，重設全庫存，重新匯入後重載正確',async s=>{const {frame,handle}=await s.planner();await s.imports('planner');await frame.locator('#importMYOB').click();await handle.evaluate(()=>{const text='Item Number\tName\tOn Hand\tCustom List 3\r\nASA241\tMint\t104\t12Unit/CTN\r\nACE005\tAce\t9\tCTN';const e=new Event('paste',{bubbles:true,cancelable:true});Object.defineProperty(e,'clipboardData',{value:{getData:()=>text}});document.querySelector('#inventoryPaste').dispatchEvent(e)});await frame.locator('#applyInventoryPaste').click();await s.page.waitForFunction(()=>window.__store['app_data/order_inventory_v1']?.rows?.ASA241?.stock===104);assert(!s.dialogs.includes('資料已變更，請重新預覽'));await frame.locator('#inventoryPasteDialog button').filter({hasText:'關閉'}).click();await frame.locator('#resetMYOBStock').click();await s.page.waitForFunction(()=>window.__store['app_data/order_inventory_v1']?.resetAt);const rows=await s.page.evaluate(()=>window.__store['app_data/order_inventory_v1'].rows);assert(Object.values(rows).every(r=>r.stock===null));assert.equal(rows.ASA241.custom,'12Unit/CTN');const f=await inventory(s,'Item Number\tOn Hand\tCustom List 3\nASA241\t104\t12Unit/CTN');await f.locator('#applyInventoryPaste').click();await s.page.waitForFunction(()=>window.__store['app_data/order_inventory_v1']?.rows?.ASA241?.stock===104);await s.page.addInitScript(store=>window.__store=store,await s.page.evaluate(()=>window.__store));await s.page.reload();const next=await s.planner();await next.handle.waitForFunction(()=>state.inventory?.ASA241?.stock===104);assert.equal(await next.handle.evaluate(()=>state.inventory.ASA241.stock),104);});
test('UI-22','欄位與閱讀','備註位於採購單位、保存期限次序、字級和本機欄寬',async s=>{const {frame}=await s.planner();const note=frame.locator('[data-item-note="ACE005"]');assert.equal(await note.locator('..').locator('..').getAttribute('class'),'purchase-unit');assert.equal(await frame.locator('#noteSection').evaluate(e=>getComputedStyle(e).backgroundColor),'rgb(237, 245, 255)');const names=await frame.locator('#plan th[data-column]').evaluateAll(th=>th.map(t=>t.dataset.column));assert.equal(names.indexOf('shelf'),names.indexOf('pi')+1);assert.equal(await frame.locator('.product-title').first().evaluate(e=>getComputedStyle(e).fontSize),'16px');const head=frame.locator('th[data-column="product"]'),handle=head.locator('.column-resizer');await handle.focus();const before=await head.evaluate(e=>e.getBoundingClientRect().width);await handle.press('ArrowRight');assert((await head.evaluate(e=>e.getBoundingClientRect().width))>before);await frame.locator('#resetColumnWidths').click();assert.equal(await head.getAttribute('style'),'');});
test('ETA-01','ETA 同步','公開表格精確配對、更新到港日並保留鎖定和其他資料',async s=>{await s.page.evaluate(()=>{window.__store['app_data/container_tracker_v1']={containers:[{code:'JSRTEST',portDate:'2026-01-01',unloadDate:'2026-02-02',history:[],notes:'Keep'},{code:'JSRLOCK',portDate:'2026-01-01',etaLocked:true}],settings:{}}});await s.page.route('https://docs.google.com/spreadsheets/**/gviz/tq?**',route=>{const url=new URL(route.request().url()),cb=url.searchParams.get('tqx').split('responseHandler:')[1];return route.fulfill({contentType:'text/javascript',body:cb+'('+JSON.stringify({status:'ok',table:{cols:[{label:'Item #'},{label:'ETA Brisbane'}],rows:[{c:[{v:'JSRTEST'},{v:'Date(2026,11,24)'}]},{c:[{v:'JSRLOCK'},{v:'Date(2026,11,25)'}]}]}})+')'})});await s.page.locator('#container-tab').click();await s.page.locator('#etaRefresh').click();await s.page.waitForFunction(()=>window.__store['app_data/container_tracker_v1']?.containers?.[0]?.portDate==='2026-12-24');const data=await s.page.evaluate(()=>window.__store['app_data/container_tracker_v1']);assert.equal(data.containers[0].notes,'Keep');assert.equal(data.containers[0].unloadDate,'2026-02-02');assert.equal(data.containers[1].portDate,'2026-01-01');assert(data.containers[0].history[0].text.includes('2026-12-24'));assert(await s.page.locator('iframe[title="Container ETAs 來源表格"]').count());});
test('UI-23','滑鼠欄寬','滑鼠拖曳原始與捲動固定表頭，欄寬同步且備註提示簡化',async s=>{await s.page.setViewportSize({width:1440,height:1100});const {frame,handle}=await s.planner();assert.equal(await frame.locator('[data-item-note="ACE005"]').getAttribute('placeholder'),'單品備註');const head=frame.locator('th[data-column="product"]');const base=await head.evaluate(e=>e.getBoundingClientRect().width);const grip=await head.locator('.column-resizer').boundingBox();await s.page.mouse.move(grip.x+grip.width/2,grip.y+grip.height/2);await s.page.mouse.down();await s.page.mouse.move(grip.x+grip.width/2+65,grip.y+grip.height/2,{steps:8});await s.page.mouse.up();assert((await head.evaluate(e=>e.getBoundingClientRect().width))>base+40);await handle.evaluate(()=>{const item=state.items[0];state.items=[...state.items,...Array.from({length:20},(_,n)=>({...item,code:'DRAG'+n}))];renderPlan()});await s.page.waitForFunction(()=>document.querySelector('#plannerFrame').getBoundingClientRect().height>3000);await s.page.evaluate(()=>window.scrollTo(0,document.querySelector('#plannerFrame').getBoundingClientRect().top+window.scrollY+900));await s.page.locator('#kaisiFrozenPlannerHead.visible').waitFor();const frozen=s.page.locator('[data-resize-column="product"]');const box=await frozen.boundingBox(),before=await head.evaluate(e=>e.getBoundingClientRect().width);await s.page.mouse.move(box.x+box.width/2,box.y+box.height/2);await s.page.mouse.down();await s.page.mouse.move(box.x+box.width/2+75,box.y+box.height/2,{steps:10});await s.page.mouse.up();await handle.waitForFunction(before=>document.querySelector('th[data-column="product"]').getBoundingClientRect().width>before+45,before);await s.page.waitForFunction(before=>document.querySelector('[data-resize-column="product"]').parentElement.getBoundingClientRect().width>before+45,before);const grown=await head.evaluate(e=>e.getBoundingClientRect().width),left=await (await s.page.waitForFunction(()=>{const el=document.querySelector('#kaisiFrozenPlannerHead.visible [data-resize-column="product"]');if(!el||!el.getClientRects().length)return false;const r=el.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height}})).jsonValue();await s.page.mouse.move(left.x+left.width/2,left.y+left.height/2);await s.page.mouse.down();await s.page.mouse.move(left.x+left.width/2-40,left.y+left.height/2,{steps:8});await s.page.mouse.up();await handle.waitForFunction(grown=>document.querySelector('th[data-column="product"]').getBoundingClientRect().width<grown-25,grown);await s.page.screenshot({path:path.join(path.dirname(reportFile),'V4141-frozen-resize.png')});});
const reportFile=path.resolve(process.env.JPT_REPORT_FILE||path.join(__dirname,'../test-results/e2e-audit.md'));
fs.mkdirSync(path.dirname(reportFile),{recursive:true});
function report(){fs.mkdirSync(path.dirname(reportFile),{recursive:true});const failed=results.filter(x=>x.status==='FAIL');let md='# E2E 測試紀錄\n\n日期：2026-10-20（Australia/Brisbane）\n\n環境：Chromium、本機 HTTP 子目錄、模擬 Firebase／角色／寫入失敗。所有外部 Firebase 要求均由測試攔截，不寫入正式資料。\n\n';md+=`已執行 ${results.length}／${tests.length}；通過 ${results.length-failed.length}；失敗 ${failed.length}。\n\n| 編號 | 範圍 | 流程 | 結果 |\n|---|---|---|---|\n`;md+=results.map(x=>`| ${x.id} | ${x.area} | ${x.name} | ${x.status} |`).join('\n')+'\n';for(const f of failed)md+=`\n## ${f.id}：${f.name}\n\n狀態：待分析及修復\n\n\`\`\`text\n${f.error}\n\`\`\`\n`;md+='\n## 邊界\n\n本次為合成資料測試，不驗證真實 Firebase Security Rules、正式帳號登入、客訂工具實際帳號或未提供的大型 Excel／CSV.GZ 檔案。另搭配既有 browser.cjs 驗證銷售 Worker、PI 原子失敗、備份下載／還原及貨櫃設定。\n';fs.writeFileSync(reportFile,md);fs.writeFileSync(reportFile.replace(/\.md$/,'.json'),JSON.stringify(results,null,2))}
require('./customer-demand.e2e.cjs')({test,reportFile});
require('./work-notes.e2e.cjs')({test});
require('./pi-quantity-defaults.e2e.cjs')({test,reportFile});
require('./pi-completeness.e2e.cjs')({test});
require('./pi-temporary.e2e.cjs')({test});
require('./pi-image-upload.e2e.cjs')({test});
require('./inventory-cloud.e2e.cjs')({test});
require('./master-search.e2e.cjs')({test});
require('./batch-dedup.e2e.cjs')({test});
require('./alias-consistency.e2e.cjs')({test});
(async()=>{const harness=await start();try{const selected=tests.filter(t=>!process.env.JPT_E2E_FILTER||t.id.match(process.env.JPT_E2E_FILTER));for(const t of selected){let s;const result={id:t.id,area:t.area,name:t.name,status:'PASS'};try{s=await harness.page(t.options);await t.run(s);assert.deepEqual(s.errors,[],'unexpected browser errors')}catch(e){result.status='FAIL';result.error=e.stack;console.log('FAIL',t.id,e.message);if(s)await s.page.screenshot({path:path.join(path.dirname(reportFile),t.id+'.png')}).catch(()=>{})}finally{if(s)await s.context.close()}results.push(result);report();if(result.status==='PASS')console.log('PASS',t.id,t.name)}console.log(JSON.stringify({total:results.length,failed:results.filter(x=>x.status==='FAIL').length,report:reportFile}));process.exitCode=results.some(x=>x.status==='FAIL')?1:0}finally{await harness.close()}})().catch(e=>{console.error(e);process.exitCode=1});
